## Apps Script

Go to **Extensions > Apps Script**, replace everything in `Code.gs`, paste this, and hit **Run > `buildFinalSheet`**. Grant permissions when prompted.

```javascript
function buildFinalSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const raw = ss.getSheetByName("Raw");
  if (!raw) throw new Error("No sheet named 'Raw' found.");

  const data = raw.getDataRange().getValues();
  const headers = data[0];
  const rows = data.slice(1);

  // Column indices (0-based) — raw columns A-F, helper columns G-P
  const COL = {
    TIMESTAMP: 0, NAME: 1, EMAIL: 2, JOINED_RAW: 3, PHONE_RAW: 4, PARK_RAW: 5,
    JOINED_CLEAN: 6, PHONE_CLEAN: 7, TIME_CLEAN: 8, PARK_CLEAN: 9,
    EMAIL_KEY: 10, NAME_KEY: 11, DUP_EMAIL: 12, DUP_NAME_TIME: 13,
    SUPERSEDED: 14, REVIEW: 15
  };

  // Build row objects
  const records = rows.map((r, i) => ({
    idx: i + 2,                               // 1-based sheet row
    timestamp:    r[COL.TIMESTAMP],
    name:         String(r[COL.NAME]).trim(),
    email:        String(r[COL.EMAIL]).trim().toLowerCase(),
    joinedRaw:    String(r[COL.JOINED_RAW]).trim(),
    phoneRaw:     String(r[COL.PHONE_RAW]).trim(),
    parkRaw:      String(r[COL.PARK_RAW]).trim(),
    joinedClean:  String(r[COL.JOINED_CLEAN]).trim(),
    phoneClean:   String(r[COL.PHONE_CLEAN]).trim(),
    parkClean:    String(r[COL.PARK_CLEAN]).trim(),
    timeClean:    r[COL.TIME_CLEAN],
    nameKey:      String(r[COL.NAME_KEY]).trim(),
    dupEmail:     String(r[COL.DUP_EMAIL]).trim(),
    dupNameTime:  String(r[COL.DUP_NAME_TIME]).trim(),
    review:       String(r[COL.REVIEW]).trim()
  }));

  // ---- Group rows ----
  // Email groups: rows that share a non-empty email
  // No-email rows: each is its own group UNLESS flagged DUP-name-time,
  //   in which case group by nameKey (only among no-email rows)
  const emailGroups = {};      // email -> [records]
  const nameTimeGroups = {};   // nameKey -> [records]  (no-email, dup-flagged)
  const soloRows = [];         // no-email, not dup-flagged

  records.forEach(rec => {
    if (rec.email) {
      if (!emailGroups[rec.email]) emailGroups[rec.email] = [];
      emailGroups[rec.email].push(rec);
    } else if (rec.dupNameTime) {
      const key = rec.nameKey;
      if (!nameTimeGroups[key]) nameTimeGroups[key] = [];
      nameTimeGroups[key].push(rec);
    } else {
      soloRows.push(rec);
    }
  });

  // ---- Merge logic ----
  const finalRows = [];
  let mergedCount = 0;
  let reviewCount = 0;

  function mergeGroup(group) {
    // Sort descending by cleaned timestamp so index 0 is most recent
    group.sort((a, b) => {
      const ta = a.timeClean instanceof Date ? a.timeClean.getTime() : 0;
      const tb = b.timeClean instanceof Date ? b.timeClean.getTime() : 0;
      return tb - ta;
    });

    const primary = group[0];
    const merged = {
      timestamp:    primary.timeClean instanceof Date ? primary.timeClean : primary.timestamp,
      name:         primary.name,
      email:        primary.email || group.find(r => r.email)?.email || "",
      joinedClean:  primary.joinedClean,
      phoneClean:   primary.phoneClean,
      parkClean:    primary.parkClean,
      sourceRows:   group.map(r => r.idx).join(", "),
      conflicts:    [],
      hasReview:    group.some(r => r.review === "REVIEW")
    };

    const fields = [
      { key: "joinedClean", label: "JoinedBefore" },
      { key: "phoneClean",  label: "Phone" },
      { key: "parkClean",   label: "PreferredPark" }
    ];

    if (group.length > 1) {
      mergedCount++;

      // Fill blanks from older copies and detect conflicts
      fields.forEach(f => {
        const values = [...new Set(
          group.map(r => r[f.key]).filter(v => v && v !== "REVIEW")
        )];
        if (!merged[f.key] || merged[f.key] === "REVIEW") {
          merged[f.key] = values[0] || merged[f.key];
        }
        if (values.length > 1) {
          merged.conflicts.push(f.label + ": " + values.join(" vs "));
        }
      });

      // Fill name if primary is blank
      if (!merged.name) {
        const alt = group.find(r => r.name);
        if (alt) merged.name = alt.name;
      }
    }

    // Build review string
    let reviewStr = "";
    if (merged.hasReview || merged.conflicts.length > 0) {
      const parts = [];
      if (merged.hasReview) parts.push("source row flagged REVIEW");
      if (merged.conflicts.length > 0) parts.push(merged.conflicts.join("; "));
      reviewStr = "REVIEW (needs manual check): " + parts.join(" | ");
      reviewCount++;
    }
    merged.reviewStr = reviewStr;

    finalRows.push(merged);
  }

  Object.values(emailGroups).forEach(mergeGroup);
  Object.values(nameTimeGroups).forEach(mergeGroup);
  soloRows.forEach(r => mergeGroup([r]));

  // ---- Write Final sheet ----
  let final = ss.getSheetByName("Final");
  if (final) {
    final.clear();
  } else {
    final = ss.insertSheet("Final");
  }

  // Summary block
  final.getRange("A1").setValue("Total raw rows");
  final.getRange("B1").setValue(records.length);
  final.getRange("A2").setValue("Rows kept (unique persons)");
  final.getRange("B2").setValue(finalRows.length);
  final.getRange("A3").setValue("Duplicate groups merged");
  final.getRange("B3").setValue(mergedCount);
  final.getRange("A4").setValue("Rows needing review");
  final.getRange("B4").setValue(reviewCount);
  final.getRange("A1:A4").setFontWeight("bold");

  // Data headers in row 6
  const outHeaders = [
    "Name", "Email", "JoinedBefore", "Phone", "PreferredPark",
    "Timestamp", "Source Rows", "Review"
  ];
  final.getRange(6, 1, 1, outHeaders.length).setValues([outHeaders]).setFontWeight("bold");

  // Data rows starting at row 7
  if (finalRows.length > 0) {
    const outData = finalRows.map(m => [
      m.name,
      m.email,
      m.joinedClean,
      m.phoneClean,
      m.parkClean,
      m.timestamp,
      m.sourceRows,
      m.reviewStr
    ]);
    final.getRange(7, 1, outData.length, outHeaders.length).setValues(outData);

    // Format timestamp column as datetime
    final.getRange(7, 6, outData.length, 1).setNumberFormat("yyyy-mm-dd hh:mm");
  }

  // Auto-resize
  outHeaders.forEach((_, i) => final.autoResizeColumn(i + 1));

  SpreadsheetApp.getUi().alert(
    "Done.\n\n" +
    "Raw rows: " + records.length + "\n" +
    "Unique persons: " + finalRows.length + "\n" +
    "Merged groups: " + mergedCount + "\n" +
    "Needs review: " + reviewCount
  );
}
