## What to expect when you run it

The script creates (or overwrites) a **Final** sheet. Rows 1–4 show the summary counts. Row 6 is the header row, and your cleaned, deduplicated data starts at row 7. The **Source Rows** column tells you which raw-sheet row numbers were combined, and the **Review** column spells out exactly which fields conflicted so you know what to look at.

For your sample data, Maya Singh's two rows would merge into one: the script keeps the later timestamp, fills any blanks from the earlier row, and since both phone values are `REVIEW` (7-digit), it flags the final row for review.

One thing to watch: the script assumes your helper columns are exactly G through P in that order. If you inserted or moved any columns, update the `COL` indices at the top of the script before running.

```javascript
function buildFinalSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const raw = ss.getSheetByName("Raw");
  if (!raw) throw new Error("No sheet named 'Raw' found.");

  const data = raw.getDataRange().getValues();
  const rows = data.slice(1);

  const COL = {
    TIMESTAMP: 0, NAME: 1, EMAIL: 2, JOINED_RAW: 3, PHONE_RAW: 4, PARK_RAW: 5,
    JOINED_CLEAN: 6, PHONE_CLEAN: 7, TIME_CLEAN: 8, PARK_CLEAN: 9,
    EMAIL_KEY: 10, NAME_KEY: 11, DUP_EMAIL: 12, DUP_NAME_TIME: 13,
    SUPERSEDED: 14, REVIEW: 15
  };

  function formatPhone(val) {
    var s = String(val).replace(/\D/g, "");
    if (s.length === 10) {
      return "(" + s.substring(0, 3) + ") " + s.substring(3, 6) + "-" + s.substring(6);
    }
    return String(val);
  }

  var records = rows.map(function (r, i) {
    return {
      idx: i + 2,
      timestamp:    r[COL.TIMESTAMP],
      timestampStr: String(r[COL.TIMESTAMP]),
      name:         String(r[COL.NAME]).trim(),
      email:        String(r[COL.EMAIL]).trim().toLowerCase(),
      joinedRaw:    String(r[COL.JOINED_RAW]).trim(),
      phoneRaw:     String(r[COL.PHONE_RAW]).trim(),
      parkRaw:      String(r[COL.PARK_RAW]).trim(),
      joinedClean:  String(r[COL.JOINED_CLEAN]).trim(),
      phoneClean:   String(r[COL.PHONE_CLEAN]).trim(),
      parkClean:    String(r[COL.PARK_CLEAN]).trim(),
      timeClean:    r[COL.TIME_CLEAN],
      nameKey:      String(r[COL.NAME_KEY]).trim(),
      dupEmail:     String(r[COL.DUP_EMAIL]).trim(),
      dupNameTime:  String(r[COL.DUP_NAME_TIME]).trim(),
      review:       String(r[COL.REVIEW]).trim(),
      rawCols:      [r[COL.TIMESTAMP], r[COL.NAME], r[COL.EMAIL],
                     r[COL.JOINED_RAW], r[COL.PHONE_RAW], r[COL.PARK_RAW]]
    };
  });

  // ---- Group rows ----
  var emailGroups = {};
  var nameTimeGroups = {};
  var soloRows = [];

  records.forEach(function (rec) {
    if (rec.email) {
      if (!emailGroups[rec.email]) emailGroups[rec.email] = [];
      emailGroups[rec.email].push(rec);
    } else if (rec.dupNameTime) {
      var key = rec.nameKey;
      if (!nameTimeGroups[key]) nameTimeGroups[key] = [];
      nameTimeGroups[key].push(rec);
    } else {
      soloRows.push(rec);
    }
  });

  // ---- Merge logic ----
  var finalRows = [];
  var mergedCount = 0;
  var reviewCount = 0;

  function mergeGroup(group) {
    group.sort(function (a, b) {
      var ta = a.timeClean instanceof Date ? a.timeClean.getTime() : 0;
      var tb = b.timeClean instanceof Date ? b.timeClean.getTime() : 0;
      return tb - ta;
    });

    var primary = group[0];
    var merged = {
      name:         primary.name,
      email:        primary.email || "",
      joinedClean:  primary.joinedClean,
      phoneClean:   primary.phoneClean,
      parkClean:    primary.parkClean,
      timestampStr: primary.timestampStr,
      rawCols:      primary.rawCols,
      sourceRows:   group.map(function (r) { return r.idx; }).join(", "),
      conflicts:    [],
      hasReview:    group.some(function (r) { return r.review === "REVIEW"; })
    };

    // Fill email from group if primary is blank
    if (!merged.email) {
      var withEmail = group.find(function (r) { return r.email; });
      if (withEmail) merged.email = withEmail.email;
    }

    var fields = [
      { key: "joinedClean", label: "JoinedBefore" },
      { key: "phoneClean",  label: "Phone" },
      { key: "parkClean",   label: "PreferredPark" }
    ];

    if (group.length > 1) {
      mergedCount++;

      fields.forEach(function (f) {
        var values = [];
        var seen = {};
        group.forEach(function (r) {
          var v = r[f.key];
          if (v && v !== "REVIEW" && !seen[v]) {
            seen[v] = true;
            values.push(v);
          }
        });
        if (!merged[f.key] || merged[f.key] === "REVIEW") {
          merged[f.key] = values[0] || merged[f.key];
        }
        if (values.length > 1) {
          merged.conflicts.push(f.label + ": " + values.join(" vs "));
        }
      });

      if (!merged.name) {
        var alt = group.find(function (r) { return r.name; });
        if (alt) merged.name = alt.name;
      }
    }

    // Format phone
    merged.phoneClean = formatPhone(merged.phoneClean);

    // Build review string
    var reviewStr = "";
    if (merged.hasReview || merged.conflicts.length > 0) {
      var parts = [];
      if (merged.hasReview) parts.push("source row flagged REVIEW");
      if (merged.conflicts.length > 0) parts.push(merged.conflicts.join("; "));
      reviewStr = "REVIEW (needs manual check): " + parts.join(" | ");
      reviewCount++;
    }
    merged.reviewStr = reviewStr;

    finalRows.push(merged);
  }

  var key;
  for (key in emailGroups) mergeGroup(emailGroups[key]);
  for (key in nameTimeGroups) mergeGroup(nameTimeGroups[key]);
  soloRows.forEach(function (r) { mergeGroup([r]); });

  // ---- Park counts ----
  var parkCounts = {};
  finalRows.forEach(function (m) {
    var p = m.parkClean || "(blank/review)";
    parkCounts[p] = (parkCounts[p] || 0) + 1;
  });
  var parkNames = Object.keys(parkCounts).sort();

  // ---- Write Final sheet ----
  var final = ss.getSheetByName("Final");
  if (final) {
    final.clear();
  } else {
    final = ss.insertSheet("Final");
  }

  // Summary block
  var summaryRow = 1;
  final.getRange(summaryRow, 1).setValue("Total raw rows");
  final.getRange(summaryRow, 2).setValue(records.length);
  summaryRow++;
  final.getRange(summaryRow, 1).setValue("Rows kept (unique persons)");
  final.getRange(summaryRow, 2).setValue(finalRows.length);
  summaryRow++;
  final.getRange(summaryRow, 1).setValue("Duplicate groups merged");
  final.getRange(summaryRow, 2).setValue(mergedCount);
  summaryRow++;
  final.getRange(summaryRow, 1).setValue("Rows needing review");
  final.getRange(summaryRow, 2).setValue(reviewCount);
  summaryRow++;

  // Blank row then park counts
  summaryRow++;
  final.getRange(summaryRow, 1).setValue("Park breakdown").setFontWeight("bold");
  summaryRow++;
  parkNames.forEach(function (p) {
    final.getRange(summaryRow, 1).setValue(p);
    final.getRange(summaryRow, 2).setValue(parkCounts[p]);
    summaryRow++;
  });

  final.getRange(1, 1, 4, 1).setFontWeight("bold");

  // Data headers two rows below the last summary row
  var headerRow = summaryRow + 1;
  var outHeaders = [
    "Name", "Email", "JoinedBefore", "Phone", "PreferredPark",
    "Timestamp (original)", "Source Rows", "Review",
    "Raw Timestamp", "Raw Name", "Raw Email",
    "Raw JoinedBefore", "Raw Phone", "Raw PreferredPark"
  ];
  final.getRange(headerRow, 1, 1, outHeaders.length)
       .setValues([outHeaders])
       .setFontWeight("bold");

  // Data rows
  var dataStart = headerRow + 1;
  if (finalRows.length > 0) {
    var outData = finalRows.map(function (m) {
      return [
        m.name,
        m.email,
        m.joinedClean,
        m.phoneClean,
        m.parkClean,
        m.timestampStr,
        m.sourceRows,
        m.reviewStr,
        m.rawCols[0],
        m.rawCols[1],
        m.rawCols[2],
        m.rawCols[3],
        m.rawCols[4],
        m.rawCols[5]
      ];
    });
    final.getRange(dataStart, 1, outData.length, outHeaders.length).setValues(outData);

    // Format raw timestamp column (I, index 9) if it came through as a Date object
    final.getRange(dataStart, 9, outData.length, 1).setNumberFormat("m/d/yyyy h:mm");
  }

  // Auto-resize columns
  for (var c = 1; c <= outHeaders.length; c++) {
    final.autoResizeColumn(c);
  }

  SpreadsheetApp.getUi().alert(
    "Done.\n\n" +
    "Raw rows: " + records.length + "\n" +
    "Unique persons: " + finalRows.length + "\n" +
    "Merged groups: " + mergedCount + "\n" +
    "Needs review: " + reviewCount
  );
}
